package org.jellylegacy.stoneage;
import android.app.*;
import android.content.*;
import android.os.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

public abstract class StoneActivity extends Activity {
    protected abstract boolean movies();
    private Api api;private LinearLayout root,body;private TextView title,status;private Button next;
    private final Handler ui=new Handler();private final ExecutorService network=Executors.newSingleThreadExecutor();
    private final ArrayList<Item> items=new ArrayList<Item>();private ArrayAdapter<Item> adapter;
    private String section,type,parent,filter,search;private int page,stamp;private boolean dead,busy;
    private final ArrayList<String[]> history=new ArrayList<String[]>();private Runnable poll;
    private interface Work{Object run()throws Exception;}private interface Done{void result(Object o);}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(13);return b;}
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(8,8,8,8);return t;}
    public void onCreate(Bundle b){super.onCreate(b);api=new Api(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.BLACK);LinearLayout bar=new LinearLayout(this);title=text(movies()?"JellyStone Video":"JellyStone Music",18);bar.addView(title,new LinearLayout.LayoutParams(0,48,1));Button menu=button("Menu");bar.addView(menu);root.addView(bar);menu.setOnClickListener(new View.OnClickListener(){public void onClick(View v){menu();}});body=new LinearLayout(this);body.setOrientation(1);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));status=text("",12);root.addView(status);
        if(!movies()){LinearLayout controls=new LinearLayout(this);for(final String action:new String[]{"Prev","Play/Pause","Next","Repeat","Stop"}){Button c=button(action);controls.addView(c,new LinearLayout.LayoutParams(0,45,1));c.setOnClickListener(new View.OnClickListener(){public void onClick(View v){Intent i=new Intent(StoneActivity.this,MusicService.class);i.putExtra("action",action);startService(i);}});}root.addView(controls);}
        setContentView(root);if(api.signedIn())show(movies()?"Movies":"Albums",movies()?"Movie":"MusicAlbum",null,null,null,false);else login();
    }
    private void work(final Work job,final Done done){final int generation=stamp;network.execute(new Runnable(){public void run(){Object result;try{result=job.run();}catch(Exception e){result=e;}final Object r=result;ui.post(new Runnable(){public void run(){if(!dead&&generation==stamp)done.result(r);}});}});}
    private boolean error(Object o){if(o instanceof Exception){status.setText(((Exception)o).getMessage());return true;}return false;}
    private void login(){stamp++;body.removeAllViews();title.setText("Connect to Jellyfin");final EditText server=new EditText(this);server.setSingleLine(true);server.setHint("https://your-server");server.setText(api.server());body.addView(server);final Button connect=button("Quick Connect");body.addView(connect);connect.setOnClickListener(new View.OnClickListener(){public void onClick(View v){api.server(server.getText().toString());connect.setEnabled(false);status.setText("Connecting securely…");work(new Work(){public Object run()throws Exception{return api.begin();}},new Done(){public void result(Object o){connect.setEnabled(true);if(error(o))return;JSONObject q=(JSONObject)o;quick(q.optString("Code"),q.optString("Secret"));}});}});}
    private void quick(String code,final String secret){body.removeAllViews();body.addView(text("Approve this code in Jellyfin → Quick Connect",17));body.addView(text(code,32));status.setText("Waiting for approval…");poll=new Runnable(){public void run(){work(new Work(){public Object run()throws Exception{return api.check(secret);}},new Done(){public void result(Object o){if(Boolean.TRUE.equals(o)){work(new Work(){public Object run()throws Exception{api.finish(secret);return true;}},new Done(){public void result(Object result){if(!error(result))show(movies()?"Movies":"Albums",movies()?"Movie":"MusicAlbum",null,null,null,false);}});}else if(!dead)ui.postDelayed(poll,5000);}});}};ui.postDelayed(poll,2000);}
    private void menu(){final String[] choices=movies()?new String[]{"Movies","TV shows","Continue watching","Favorites","Search","Previous page","Refresh","Log out"}:new String[]{"Albums","Songs","Favorites","Offline songs","Download favorites","Search","Previous page","Refresh","Log out"};new AlertDialog.Builder(this).setItems(choices,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){String s=choices[n];if(s.equals("Log out")){api.logout();history.clear();login();return;}if(s.equals("Previous page")){if(!busy&&page>1){page-=2;load();}return;}if(s.equals("Refresh")){show(section,type,parent,filter,search,false);return;}if(s.equals("Search")){search();return;}if(s.equals("Offline songs")){offline();return;}if(s.equals("Download favorites")){downloadFavorites();return;}if(!api.signedIn()){login();return;}history.clear();show(s,s.equals("Movies")?"Movie":s.equals("TV shows")?"Series":s.equals("Albums")?"MusicAlbum":movies()?"Movie,Episode":"Audio",null,s.equals("Favorites")?"IsFavorite":s.equals("Continue watching")?"IsResumable":null,null,false);}}).show();}
    private void search(){final EditText input=new EditText(this);new AlertDialog.Builder(this).setTitle("Search").setView(input).setPositiveButton("Search",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){show("Search",movies()?"Movie,Series,Episode":"Audio",null,null,input.getText().toString(),true);}}).setNegativeButton("Cancel",null).show();}
    private void show(String s,String t,String p,String f,String q,boolean push){if(poll!=null)ui.removeCallbacks(poll);if(push&&section!=null)history.add(new String[]{section,type,parent,filter,search});stamp++;busy=false;section=s;type=t;parent=p;filter=f;search=q;page=0;items.clear();buildList();load();}
    private void buildList(){body.removeAllViews();title.setText(section);ListView list=new ListView(this);list.setCacheColorHint(Color.BLACK);adapter=new ArrayAdapter<Item>(this,android.R.layout.simple_list_item_1,items){public View getView(int pos,View view,ViewGroup parent){TextView row=(TextView)super.getView(pos,view,parent);row.setTextColor(Color.WHITE);row.setTextSize(15);row.setMaxLines(2);return row;}};next=button("Loading…");list.addFooterView(next,null,false);list.setAdapter(adapter);body.addView(list,new LinearLayout.LayoutParams(-1,0,1));next.setOnClickListener(new View.OnClickListener(){public void onClick(View v){load();}});list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> p,View v,int pos,long id){if(pos>=items.size())return;final Item item=items.get(pos);if(item.type.equals("MusicAlbum"))show(item.name,"Audio",item.id,null,null,true);else if(item.type.equals("Series"))show(item.name,"Season",item.id,null,null,true);else if(item.type.equals("Season"))show(item.name,"Episode",item.id,null,null,true);else detail(item);}});}
    private void load(){if(busy)return;busy=true;next.setEnabled(false);status.setText("Loading…");final String t=type,p=parent,f=filter,q=search;final int pg=page;work(new Work(){public Object run()throws Exception{return api.list(t,p,f,q,pg);}},new Done(){public void result(Object o){busy=false;if(error(o)){next.setText("Retry");next.setEnabled(true);return;}ArrayList<Item> batch=(ArrayList<Item>)o;items.clear();items.addAll(batch);page++;adapter.notifyDataSetChanged();title.setText(section+" · "+page);next.setText(batch.size()==30?"Next page":"End of list");next.setEnabled(batch.size()==30);status.setText(items.size()+" titles on this page");}});}
    private void detail(final Item item){final String[] options=movies()?new String[]{item.resume>0?"Resume":"Play","Play from beginning",item.favorite?"Remove favorite":"Add favorite",item.watched?"Mark unwatched":"Mark watched"}:new String[]{"Play from here",item.favorite?"Remove favorite":"Add favorite"};new AlertDialog.Builder(this).setTitle(item.name).setItems(options,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){String s=options[n];if(s.startsWith("Play")||s.equals("Resume")){if(movies()){Intent i=new Intent(StoneActivity.this,VideoPlayer.class);i.putExtra("id",item.id);i.putExtra("title",item.name);i.putExtra("start",s.equals("Resume")?item.resume:0L);startActivity(i);}else{ArrayList<String> ids=new ArrayList<String>(),names=new ArrayList<String>();for(Item m:items){ids.add(m.id);names.add(m.name);}Intent i=new Intent(StoneActivity.this,MusicService.class);i.putExtra("action","Play");i.putStringArrayListExtra("ids",ids);i.putStringArrayListExtra("names",names);i.putExtra("index",items.indexOf(item));startService(i);status.setText("Loading "+item.name+"…");}}else{final boolean fav=s.indexOf("favorite")>=0,value=s.startsWith("Add")||s.equals("Mark watched");work(new Work(){public Object run()throws Exception{if(fav)api.favorite(item.id,value);else api.watched(item.id,value);return true;}},new Done(){public void result(Object o){if(!error(o)){status.setText("Saved");show(section,type,parent,filter,search,false);}}});}}}).show();}
    private void offline(){stamp++;section="Offline songs";items.clear();try{JSONObject index=new JSONObject(getSharedPreferences("offline",0).getString("index","{}"));Iterator keys=index.keys();while(keys.hasNext()){String id=(String)keys.next();if(new File(getFilesDir(),id+".mp3").exists()){Item i=new Item();i.id=id;i.name=index.optString(id);i.type="Audio";i.info="Downloaded";items.add(i);}}}catch(Exception ignored){}buildList();adapter.notifyDataSetChanged();next.setEnabled(false);next.setText("Offline library");status.setText(items.size()+" downloaded songs");}
    private void downloadFavorites(){status.setText("Downloading favorites…");work(new Work(){public Object run()throws Exception{JSONObject index=new JSONObject(getSharedPreferences("offline",0).getString("index","{}"));int count=0;for(int pg=0;;pg++){ArrayList<Item> batch=api.list("Audio",null,"IsFavorite",null,pg);for(Item item:batch){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");File target=new File(getFilesDir(),item.id+".mp3");if(!target.exists()){File tmp=new File(getFilesDir(),item.id+".part");api.download(api.music(item.id),tmp,null);if(!tmp.renameTo(target))throw new IOException("Could not save song");count++;}index.put(item.id,item.name);getSharedPreferences("offline",0).edit().putString("index",index.toString()).commit();}if(batch.size()<30)break;}return Integer.valueOf(count);}},new Done(){public void result(Object o){if(!error(o)){offline();status.setText(o+" new songs downloaded");}}});}
    public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MENU){menu();return true;}if(key==KeyEvent.KEYCODE_BACK&&history.size()>0){String[] h=history.remove(history.size()-1);show(h[0],h[1],h[2],h[3],h[4],false);return true;}return super.onKeyDown(key,event);}
    protected void onDestroy(){dead=true;stamp++;if(poll!=null)ui.removeCallbacks(poll);network.shutdownNow();super.onDestroy();}
}
